files.content:
body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  min-block-size: 100dvh;
}

.wrapper {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  align-items: center;
  inline-size: 50%;
}

.image {
  object-fit: cover;
  min-inline-size: 200px;
  inline-size: 100%;
  block-size: 100%;
  mix-blend-mode: multiply;
}

.wrapper:hover .image {
  position: absolute;
  transform: translateY(-50%);
  inset-block-start: 50%;
  inset-inline-start: 50%;
  inline-size: 25%;
  block-size: fit-content;
  translate: -50% 0;
}
